import os
import google_auth_oauthlib.flow

def oauth_callback(payload, config=None):
    config = config or {}
    client_config = {
        "web": {
            "client_id": config.get("client_id", os.environ.get("GOOGLE_CLIENT_ID")),
            "client_secret": config.get("client_secret", os.environ.get("GOOGLE_CLIENT_SECRET")),
            "auth_uri": "https://accounts.google.com/o/oauth2/auth",
            "token_uri": "https://oauth2.googleapis.com/token"
        }
    }
    flow = google_auth_oauthlib.flow.Flow.from_client_config(
        client_config,
        scopes=config.get("scopes", ["openid", "profile", "email"])
    )
    flow.redirect_uri = config.get("redirect_uri", os.environ.get("GOOGLE_REDIRECT_URI"))
    authorization_response = payload.get("authorization_response")
    flow.fetch_token(authorization_response=authorization_response)
    credentials = flow.credentials
    result = {
        "access_token": credentials.token,
        "refresh_token": credentials.refresh_token,
        "id_token": credentials.id_token,
        "expires_at": credentials.expires_at
    }
    return result
